   260|
   261|  if (!error || typeof error !== 'object') {
   262|    return null;
   263|  }
   264|
   265|  const record = error as Record<string, unknown>;
   266|  const directKeys = ['message', 'msg', 'details', 'reason', 'error_description'] as const;
   267|
   268|  for (const key of directKeys) {
   269|    const candidate = record[key];
   270|    if (typeof candidate === 'string' && candidate.trim()) {
   271|      return candidate;
