   273|  }
   274|
   275|  const nestedError = record.error;
   276|  if (typeof nestedError === 'string' && nestedError.trim()) {
   277|    return nestedError;
   278|  }
   279|
   280|  if (nestedError && typeof nestedError === 'object') {
   281|    const nestedMessage = (nestedError as Record<string, unknown>).message;
   282|    if (typeof nestedMessage === 'string' && nestedMessage.trim()) {
