   435|async function withTimeout<T>(operation: () => Promise<T>, timeoutMs: number, label: string, fallbackValue: T): Promise<T> {
   436|  return await new Promise<T>((resolve, reject) => {
   437|    let settled = false;
   438|
   439|    const timeout = setTimeout(() => {
   440|      if (settled) {
   441|        return;
   442|      }
   443|
   444|      settled = true;
   445|      console.log('[Auth] Operation timed out:', label, timeoutMs, 'ms');
   446|      resolve(fallbackValue);
   447|    }, timeoutMs);
   448|
   449|    void operation()
   450|      .then((result) => {
   451|        if (settled) {
   452|          return;
   453|        }
   454|
   455|        settled = true;
   456|        clearTimeout(timeout);
   457|        resolve(result);
   458|      })
   459|      .catch((error) => {
   460|        if (settled) {
   461|          return;
   462|        }
   463|
   464|        settled = true;
   465|        clearTimeout(timeout);
   466|        reject(error);
   467|      });
   468|  });
   469|}
