    37|
    38|function classifyError(error: Error): ErrorCategory {
    39|  const msg = (error.message || '').toLowerCase();
    40|  if (msg.includes('maximum update depth') || msg.includes('render')) return 'RENDER_ERROR';
    41|  if (msg.includes('auth') || msg.includes('session') || msg.includes('token')) return 'AUTH_ERROR';
    42|  if (msg.includes('network') || msg.includes('fetch') || msg.includes('timeout')) return 'NETWORK_ERROR';
    43|  if (msg.includes('supabase url') || msg.includes('config')) return 'CONFIG_ERROR';
    44|  if (msg.includes('data') || msg.includes('parse') || msg.includes('json')) return 'DATA_ERROR';
    45|  return 'UNKNOWN_ERROR';
    46|}
